import re
from flask import Flask, request, jsonify

app = Flask(__name__)


def safe_eval(expression: str) -> str:
    """Evaluate a simple arithmetic expression safely.

    Only allows integers, floating point numbers, and the operators
    +, -, *, /, ** (exponentiation), and parentheses.
    """
    # Remove all whitespace to simplify validation
    expr = expression.replace(" ", "")

    # Allow only digits, decimal point, operators and parentheses
    if not re.fullmatch(r"[0-9+\-*/().eE]+", expr):
        raise ValueError("Invalid characters in expression")

    # Further sanity check: ensure the expression only contains
    # numbers, operators and parentheses (no function calls, imports, etc.)
    # This regex checks the whole string structure
    if not re.fullmatch(
        r"(?:\d+(?:\.\d+)?|[+\-*/()eE])+", expr
    ) and not re.fullmatch(r"\d+(?:\.\d+)?(?:[+\-*/]\d+(?:\.\d+)?)*", expr):
         # Allow simple chained expressions like "1+2*3"
         pass  # The regex above is permissive; we rely on Python's eval for the actual math

    # Evaluate in a restricted namespace to prevent code injection
    try:
        result = eval(expr, {"__builtins__": None}, {})
    except Exception as exc:
        raise ValueError(f"Evaluation error: {exc}")

    # Return as string, matching the OpenAPI example format
    return str(result)


@app.route("/calculator", methods=["POST"])
def calculator():
    data = request.get_json(silent=True)
    if not data or "expression" not in data:
        return jsonify({"error": "Missing 'expression' in request body"}), 400

    expression = data.get("expression")
    if not isinstance(expression, str) or not expression.strip():
        return jsonify({"error": "Expression must be a non-empty string"}), 400

    try:
        result = safe_eval(expression)
    except ValueError as ve:
        return jsonify({"error": str(ve)}), 400

    return jsonify({"result": result}), 200


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
